const initSqlJs = require('sql.js');
const fs = require('fs');
initSqlJs().then(SQL => {
  const buf = fs.readFileSync('/workspace/world.db');
  const db = new SQL.Database(buf);
  // Search for Daniel Ortiz
  let rows = db.exec(\"SELECT * FROM ts_contacts WHERE name LIKE '%Daniel%' OR name LIKE '%Ortiz%'\");
  if (rows.length > 0) {
    console.log('Found Daniel Ortiz:');
    const cols = rows[0].columns;
    rows[0].values.forEach(r => {
      const obj = {};
      cols.forEach((c,i) => obj[c] = r[i]);
      console.log(JSON.stringify(obj, null, 2));
    });
  } else {
    console.log('No match. All contacts:');
    let all = db.exec('SELECT * FROM ts_contacts');
    if (all.length > 0) {
      const cols = all[0].columns;
      all[0].values.forEach(r => {
        const obj = {};
        cols.forEach((c,i) => obj[c] = r[i]);
        console.log(JSON.stringify(obj, null, 2));
      });
    }
  }
  db.close();
});
"

node -e "
const initSqlJs = require('sql.js');
const fs = require('fs');
const crypto = require('crypto');

initSqlJs().then(SQL => {
  const buf = fs.readFileSync('/workspace/world.db');
  const db = new SQL.Database(buf);

  // 1. Check cellular service
  const settings = db.exec('SELECT cellular FROM ts_device_settings');
  if (settings.length === 0 || !settings[0].values[0][0]) {
    console.log('ERROR: Cellular service is not enabled');
    db.close();
    return;
  }
  console.log('Cellular service: ON');

  // 2. Find self contact
  const selfContact = db.exec('SELECT person_id, phone_number FROM ts_contacts WHERE is_self = 1');
  if (selfContact.length === 0 || selfContact[0].values.length !== 1) {
    console.log('ERROR: Could not find exactly 1 self entry');
    db.close();
    return;
  }
  const selfId = selfContact[0].values[0][0];
  const selfPhone = selfContact[0].values[0][1];
  console.log('Sender (self):', selfId, selfPhone);

  // 3. Find recipient
  const recipient = db.exec(\"SELECT person_id FROM ts_contacts WHERE phone_number = '+1-347-555-0169'\");
  const recipientId = recipient.length > 0 ? recipient[0].values[0][0] : null;
  console.log('Recipient person_id:', recipientId);

  // 4. Insert message
  const messageId = crypto.randomUUID();
  const content = 'Hi Daniel, just checking in to confirm your availability for cleaning this week. Let me know what days work for you. Thanks!';
  const timestamp = Date.now() / 1000;

  db.run(
    'INSERT INTO ts_messages (message_id, sender_person_id, sender_phone_number, recipient_person_id, recipient_phone_number, content, creation_timestamp) VALUES (?, ?, ?, ?, ?, ?, ?)',
    [messageId, selfId, selfPhone, recipientId, '+1-347-555-0169', content, timestamp]
  );

  // Save back to disk
  const data = db.export();
  const buffer = Buffer.from(data);
  fs.writeFileSync('/workspace/world.db', buffer);

  console.log('Message sent successfully!');
  console.log('Message ID:', messageId);

  // 5. Verify
  const verify = db.exec('SELECT * FROM ts_messages WHERE message_id = \"' + messageId + '\"');
  if (verify.length > 0) {
    const cols = verify[0].columns;
    const obj = {};
    cols.forEach((c, i) => obj[c] = verify[0].values[0][i]);
    console.log('Verified message record:');
    console.log(JSON.stringify(obj, null, 2));
  }

  db.close();
});
"
